solution:
function permute(nums) {
  const result = [];
  const current = [];
  const used = new Set();                  // indexes already placed in current

  function explore() {
    if (current.length === nums.length) {  // base case: a full ordering
      result.push([...current]);
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used.has(i)) continue;           // skip numbers already placed
      used.add(i);                         // choose
      current.push(nums[i]);
      explore();                           // explore
      current.pop();                       // un-choose (both pieces of state!)
      used.delete(i);
    }
  }

  explore();
  return result;
}

