const all = permute([0,1,2,3]);
assertEqual(all.length, 24);
assert(all.every((p) => p.length === 4 && [...p].sort().join() === '0,1,2,3'), 'each ordering must contain 0,1,2,3 once');

const all = permute([1,2,3,4,5,6,7]);
assertEqual(all.length, 5040);
assertEqual(new Set(all.map((p) => p.join())).size, 5040, 'orderings must all be different');
